<script setup>
import { computed, onMounted, reactive, ref } from 'vue'

const identity = JSON.parse(document.querySelector('#app')?.dataset.user || '{}')
const can = (permission) => identity.permissions?.includes(permission)
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || ''
const summary = ref(null)
const rows = ref([])
const pagination = ref(null)
const busy = ref(false)
const saving = ref(false)
const fxLoading = ref(false)
const fxMessage = ref('')
const fxError = ref('')
const liveFxQuote = ref(null)
const error = ref('')
const notice = ref('')
const filters = reactive({ from: '', to: '', status: '', model: '', department: '', module: '', request_type: '', search: '', page: 1 })
const budget = reactive({ year: new Date().getFullYear(), month: new Date().getMonth() + 1, budget_php: '', warning_percent: 50, critical_percent: 80 })
const price = reactive({ model: '', input_usd_per_million: '', cached_input_usd_per_million: '', output_usd_per_million: '', source_url: '', verified_at: new Date().toISOString().slice(0, 16), effective_at: new Date().toISOString().slice(0, 16), expires_at: '' })
const fx = reactive({ rate: '', source: '', source_url: '', override_reason: '', verified_at: new Date().toISOString().slice(0, 16), effective_at: new Date().toISOString().slice(0, 16), expires_at: '' })
const daily = computed(() => summary.value?.daily || [])
const maxRequests = computed(() => Math.max(1, ...daily.value.map((item) => item.requests || 0)))
const spendLabel = computed(() => summary.value?.estimated_cost_php == null ? 'Unavailable' : peso(summary.value.estimated_cost_php))

function peso(value) { return `₱${Number(value).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function time(value) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—' }
function queryString(values) { const params = new URLSearchParams(); Object.entries(values).forEach(([key, value]) => { if (value !== '' && value != null) params.set(key, value) }); return params.toString() }
async function api(url, method = 'GET', body = null) {
  const response = await fetch(url, { method, credentials: 'same-origin', headers: { Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf } : {}) }, ...(body ? { body: JSON.stringify(body) } : {}) })
  const payload = response.headers.get('content-type')?.includes('application/json') ? await response.json() : null
  if (!response.ok) throw new Error(payload?.message || `Request failed (${response.status}).`)
  return payload
}
async function load() {
  busy.value = true; error.value = ''
  try {
    const [stats, result] = await Promise.all([api('/api/admin/ai-usage/summary'), api(`/api/admin/ai-usage?${queryString({ ...filters, per_page: 25 })}`)])
    summary.value = stats
    rows.value = result.data.data || []
    pagination.value = result.data
    budget.budget_php = stats.budget_php ?? ''
  } catch (cause) { error.value = cause.message || 'AI usage data could not be loaded.' }
  finally { busy.value = false }
}
async function submitForm(url, body, message) {
  saving.value = true; error.value = ''; notice.value = ''
  try { await api(url, url.includes('budget') ? 'PUT' : 'POST', body); notice.value = message; await load() }
  catch (cause) { error.value = cause.message || 'Changes could not be saved.' }
  finally { saving.value = false }
}
function savePrice() { return submitForm('/api/admin/ai-usage/prices', { ...price, verified_at: new Date(price.verified_at).toISOString(), effective_at: new Date(price.effective_at).toISOString(), expires_at: price.expires_at ? new Date(price.expires_at).toISOString() : null }, 'Verified model price saved. New usage will use it for the effective period.') }
function saveFx() { fx.verified_at = new Date().toISOString().slice(0, 16); return submitForm('/api/admin/ai-usage/exchange-rates', { ...fx, verified_at: new Date(fx.verified_at).toISOString(), effective_at: new Date(fx.effective_at).toISOString(), expires_at: fx.expires_at ? new Date(fx.expires_at).toISOString() : null }, 'Verified USD/PHP rate saved.') }
async function fetchFx() {
  fxLoading.value = true; fxError.value = ''; fxMessage.value = ''
  try {
    const result = await api('/api/admin/ai-usage/exchange-rates/latest')
    liveFxQuote.value = result.rate
  } catch (cause) { fxError.value = cause.message || 'The latest exchange rate could not be fetched.' }
  finally { fxLoading.value = false }
}
function useLiveFxRate() {
  if (!liveFxQuote.value) return
  const quote = liveFxQuote.value
    fx.rate = quote.rate
    fx.source = quote.source
    fx.source_url = quote.source_url
    fx.verified_at = new Date().toISOString().slice(0, 16)
    fx.effective_at = `${quote.date}T12:00`
    fx.override_reason = `Fetched daily reference rate dated ${quote.date}; administrator reviewed before saving.`
    fxMessage.value = 'Latest reference copied to the form. Review it and save only if it meets your approved Finance policy.'
}
function saveBudget() { return submitForm('/api/admin/ai-usage/budget', { ...budget, budget_php: Number(budget.budget_php) }, 'Monthly AI budget saved.') }
function changePage(page) { filters.page = page; load() }
onMounted(() => { load(); if (can('admin.ai-fx.manage')) fetchFx() })
</script>

<template>
  <main class="ai-usage-page">
    <header class="ai-usage-heading"><div><p class="ai-usage-kicker">ADMINISTRATION / AI GOVERNANCE</p><h1>AI Usage &amp; Cost Monitoring</h1><p>Track provider requests, token consumption, verified PHP estimates and monthly budget thresholds.</p></div><div class="ai-usage-actions"><a v-if="can('admin.ai-usage.export')" class="ai-usage-button secondary" :href="`/admin/ai-usage/export?${queryString(filters)}`">Export CSV</a><button class="ai-usage-button secondary" :disabled="busy" @click="load">{{ busy ? 'Refreshing…' : 'Refresh' }}</button></div></header>
    <div v-if="error" class="ai-usage-alert error" role="alert">{{ error }}</div><div v-if="notice" class="ai-usage-alert success" role="status">{{ notice }}</div>
    <section class="ai-usage-kpis" aria-label="Current month usage">
      <article><small>Requests this month</small><strong>{{ summary?.requests ?? '—' }}</strong><span>{{ summary?.successful ?? 0 }} successful · {{ summary?.failed ?? 0 }} failed</span></article>
      <article><small>Input tokens</small><strong>{{ (summary?.input_tokens ?? 0).toLocaleString() }}</strong><span>Recorded provider usage</span></article>
      <article><small>Output tokens</small><strong>{{ (summary?.output_tokens ?? 0).toLocaleString() }}</strong><span>Recorded provider usage</span></article>
      <article><small>Estimated cost (PHP)</small><strong>{{ spendLabel }}</strong><span>{{ summary?.costed_requests ?? 0 }} of {{ summary?.requests ?? 0 }} requests priced</span></article>
    </section>
    <section class="ai-usage-grid">
      <article class="ai-usage-card ai-usage-chart"><div class="ai-usage-card-head"><div><h2>Daily request activity</h2><p>Current month · request count</p></div><span class="ai-usage-pill">{{ summary?.period?.from || 'Loading' }} – {{ summary?.period?.to || '' }}</span></div><div v-if="daily.length" class="ai-usage-bars" role="img" aria-label="Daily request activity chart"><div v-for="item in daily" :key="item.day" class="ai-usage-bar-col"><span :title="`${item.requests} requests on ${item.day}`" class="ai-usage-bar" :style="{ height: `${Math.max(5, item.requests / maxRequests * 100)}%` }"></span><small>{{ item.day.slice(8) }}</small></div></div><div v-else class="ai-usage-empty">{{ busy ? 'Loading activity…' : 'No requests recorded for this period.' }}</div></article>
      <article class="ai-usage-card"><div class="ai-usage-card-head"><div><h2>Pricing &amp; currency status</h2><p>Current model: <b>{{ summary?.current_model || '—' }}</b></p></div></div><dl class="ai-usage-status"><div><dt>Verified model price</dt><dd :class="summary?.pricing_available ? 'good' : 'pending'">{{ summary?.pricing_available ? `Verified ${time(summary?.pricing_verified_at)}` : 'Unavailable' }}</dd></div><div><dt>USD / PHP conversion</dt><dd :class="summary?.fx_available ? 'good' : 'pending'">{{ summary?.fx_available ? `${summary.usd_php_rate} · ${summary.fx_source}` : 'Unavailable' }}</dd></div><div><dt>Cost coverage</dt><dd>{{ summary?.cost_coverage === 'complete' ? 'Complete' : summary?.cost_coverage === 'partial' ? 'Partial' : 'Unavailable' }}</dd></div><div><dt>Monthly budget</dt><dd>{{ summary?.budget_php == null ? 'Not configured' : peso(summary.budget_php) }}</dd></div></dl><p class="ai-usage-note">Unavailable values are not estimated or replaced with zero. Model prices require a verified source and effective date.</p></article>
    </section>
    <section class="ai-usage-grid ai-usage-breakdowns"><article class="ai-usage-card"><h2>Usage by department</h2><div v-if="summary?.departments?.length" class="ai-usage-department-list"><div v-for="item in summary.departments" :key="item.department"><span><b>{{ item.department }}</b><small>{{ item.requests }} requests</small></span><strong>{{ item.cost_php == null ? 'Unavailable' : peso(item.cost_php) }}</strong></div></div><p v-else class="ai-usage-empty">No department usage has been recorded.</p><h2 class="ai-usage-subheading">Usage by module</h2><div v-if="summary?.modules?.length" class="ai-usage-department-list"><div v-for="item in summary.modules" :key="item.module"><span><b>{{ item.module.replaceAll('_', ' ') }}</b><small>{{ item.requests }} requests</small></span><strong>{{ item.cost_php == null ? 'Unavailable' : peso(item.cost_php) }}</strong></div></div></article><article class="ai-usage-card"><h2>Verified model pricing history</h2><div v-if="summary?.pricing_history?.length" class="ai-usage-history-list"><div v-for="(item, index) in summary.pricing_history" :key="`${item.model}-${item.effective_at}-${index}`"><b>{{ item.model }}</b><small>Input ${{ item.input_usd_per_million }} / 1M · Output ${{ item.output_usd_per_million }} / 1M</small><small>Verified {{ time(item.verified_at) }} · effective {{ time(item.effective_at) }}</small><a :href="item.source_url" target="_blank" rel="noopener noreferrer">Price source</a></div></div><p v-else class="ai-usage-empty">No verified model prices have been entered.</p></article><article class="ai-usage-card"><h2>Verified rate history</h2><div v-if="summary?.fx_history?.length" class="ai-usage-history-list"><div v-for="(item, index) in summary.fx_history" :key="`${item.effective_at}-${index}`"><b>{{ item.rate }} PHP / USD</b><small>{{ item.source }} · effective {{ time(item.effective_at) }}</small><small>{{ item.override_reason }}</small><a v-if="item.source_url" :href="item.source_url" target="_blank" rel="noopener noreferrer">Source reference</a></div></div><p v-else class="ai-usage-empty">No verified exchange rate has been entered.</p></article></section>
    <section class="ai-usage-card"><div class="ai-usage-card-head"><div><h2>Usage records</h2><p>Filter requests by date, user, model, module, department and outcome.</p></div><span class="ai-usage-pill">{{ pagination?.total ?? 0 }} records</span></div><form class="ai-usage-filters" @submit.prevent="filters.page = 1; load()"><label>From<input v-model="filters.from" type="date"></label><label>To<input v-model="filters.to" type="date"></label><label>Status<select v-model="filters.status"><option value="">All statuses</option><option value="success">Successful</option><option value="error">Failed</option></select></label><label>Model<input v-model="filters.model" placeholder="All models"></label><label>Department<select v-model="filters.department"><option value="">All departments</option><option v-for="name in ['Sales','Operations','Transport','Forwarding','Accounting','Billing','Finance','Executive']" :key="name" :value="name">{{ name }}</option></select></label><label>Module<input v-model="filters.module" placeholder="All modules"></label><label>Request category<select v-model="filters.request_type"><option value="">All categories</option><option value="assistant">Assistant</option><option value="connection_test">Connection test</option></select></label><label>User<input v-model="filters.search" placeholder="Name or email"></label><button class="ai-usage-button primary" :disabled="busy">Apply filters</button><button type="button" class="ai-usage-button secondary" @click="Object.assign(filters, { from: '', to: '', status: '', model: '', department: '', module: '', request_type: '', search: '', page: 1 }); load()">Reset</button></form><div class="ai-usage-table-wrap"><table class="ai-usage-table"><thead><tr><th>Time / User</th><th>Department</th><th>Module</th><th>Request</th><th>Model</th><th>Status</th><th>Tokens</th><th>Estimated cost</th><th>Latency</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ time(row.created_at) }}</b><small>{{ row.user?.name || 'System / test' }}</small></td><td>{{ row.department || '—' }}</td><td>{{ (row.module || 'assistant').replaceAll('_', ' ') }}</td><td>{{ (row.request_type || 'assistant').replaceAll('_', ' ') }}</td><td>{{ row.model || '—' }}</td><td><span :class="['ai-usage-status-badge', row.status === 'success' ? 'ok' : 'failed']">{{ row.status }}<small v-if="row.error_category"> · {{ row.error_category.replaceAll('_', ' ') }}</small></span></td><td>{{ row.input_tokens ?? '—' }} in / {{ row.output_tokens ?? '—' }} out</td><td><b>{{ row.estimated_cost_php == null ? 'Unavailable' : peso(row.estimated_cost_php) }}</b><small>{{ (row.cost_status || 'pending pricing').replaceAll('_', ' ') }}</small></td><td>{{ row.latency_ms == null ? '—' : `${row.latency_ms} ms` }}</td></tr><tr v-if="!rows.length"><td colspan="9" class="ai-usage-empty">{{ busy ? 'Loading usage records…' : 'No usage records match these filters.' }}</td></tr></tbody></table></div><div v-if="pagination && pagination.last_page > 1" class="ai-usage-pagination"><span>Page {{ pagination.current_page }} of {{ pagination.last_page }}</span><div><button class="ai-usage-button secondary" :disabled="pagination.current_page <= 1 || busy" @click="changePage(pagination.current_page - 1)">Previous</button><button class="ai-usage-button secondary" :disabled="pagination.current_page >= pagination.last_page || busy" @click="changePage(pagination.current_page + 1)">Next</button></div></div></section>
    <section class="ai-usage-management">
      <article v-if="can('admin.ai-budget.manage')" class="ai-usage-card"><h2>Monthly budget · PHP</h2><p>Budget alerts are recorded once per configured threshold. They do not send external notifications.</p><form class="ai-usage-form" @submit.prevent="saveBudget"><label>Year<input v-model.number="budget.year" type="number" min="2020" max="2100" required></label><label>Month<input v-model.number="budget.month" type="number" min="1" max="12" required></label><label>Budget (₱)<input v-model="budget.budget_php" type="number" min="0.01" step="0.01" required></label><label>Warning at (%)<input v-model.number="budget.warning_percent" type="number" min="1" max="99" required></label><label>Critical at (%)<input v-model.number="budget.critical_percent" type="number" min="2" max="100" required></label><button class="ai-usage-button primary" :disabled="saving">Save budget</button></form><div v-if="summary?.budget_alerts?.length" class="ai-usage-alert warning">Budget thresholds reached: {{ summary.budget_alerts.map(alert => `${alert.threshold_percent}%`).join(', ') }}</div></article>
      <article v-if="can('admin.ai-pricing.manage')" class="ai-usage-card"><h2>Verified model price</h2><p>Add published provider rates with source and effective dates. This creates a versioned history record.</p><form class="ai-usage-form" @submit.prevent="savePrice"><label>Model<input v-model="price.model" required maxlength="100" placeholder="Exact provider model ID"></label><label>Input USD / 1M<input v-model="price.input_usd_per_million" type="number" min="0" step="0.0000000001" required></label><label>Cached input USD / 1M<input v-model="price.cached_input_usd_per_million" type="number" min="0" step="0.0000000001"></label><label>Output USD / 1M<input v-model="price.output_usd_per_million" type="number" min="0" step="0.0000000001" required></label><label>Official price source URL<input v-model="price.source_url" type="url" required></label><label>Verified at<input v-model="price.verified_at" type="datetime-local" required></label><label>Effective at<input v-model="price.effective_at" type="datetime-local" required></label><button class="ai-usage-button primary" :disabled="saving">Save verified price</button></form></article>
      <article v-if="can('admin.ai-fx.manage')" class="ai-usage-card"><h2>USD to PHP rate</h2><p>Latest published FX reference from Frankfurter.</p><div class="ai-usage-live-fx" aria-live="polite"><template v-if="liveFxQuote"><strong>{{ liveFxQuote.rate }} PHP per USD</strong><span>Reference date: {{ liveFxQuote.date }} · fetched {{ time(liveFxQuote.fetched_at) }}</span><a :href="liveFxQuote.source_url" target="_blank" rel="noopener noreferrer">View source</a></template><span v-else-if="fxLoading">Loading latest reference rate…</span><span v-else>No live reference is available.</span><button type="button" class="ai-usage-button secondary" :disabled="fxLoading || saving" @click="fetchFx">{{ fxLoading ? 'Refreshing…' : 'Refresh FX rate' }}</button><button v-if="liveFxQuote" type="button" class="ai-usage-button secondary" :disabled="saving" @click="useLiveFxRate">Use this rate in form</button></div><p class="ai-usage-note">Daily mid-market reference rate, not a real-time trading quote. The value is not saved or applied to cost calculations until you review and submit it.</p><p v-if="fxError" class="ai-usage-alert error" role="alert">{{ fxError }}</p><p v-if="fxMessage" class="ai-usage-alert success" role="status">{{ fxMessage }}</p><form class="ai-usage-form" @submit.prevent="saveFx"><label>PHP per USD<input v-model="fx.rate" type="number" min="0.0000000001" step="0.0000000001" required></label><label>Source<input v-model="fx.source" required maxlength="120" placeholder="Provider / official reference"></label><label>Source URL<input v-model="fx.source_url" type="url"></label><label>Verified at<input v-model="fx.verified_at" type="datetime-local" required></label><label>Effective at<input v-model="fx.effective_at" type="datetime-local" required></label><label>Override reason / approval reference<textarea v-model="fx.override_reason" required minlength="8" maxlength="1000" rows="2"></textarea></label><button class="ai-usage-button primary" :disabled="saving">Save verified rate</button></form></article>
    </section>
  </main>
</template>

<style scoped>
.ai-usage-department-list,.ai-usage-history-list{display:grid;gap:10px;margin-top:14px}.ai-usage-department-list>div{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid #edf1f5}.ai-usage-department-list small,.ai-usage-history-list small{display:block;color:#71859a;margin-top:3px}.ai-usage-history-list>div{padding:8px 0;border-bottom:1px solid #edf1f5}.ai-usage-history-list a{display:inline-block;margin-top:4px;color:#17618b;font-size:12px}
.ai-usage-page{display:grid;gap:20px;color:#16334f}.ai-usage-heading,.ai-usage-card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.ai-usage-heading h1{margin:4px 0 6px;font:700 clamp(25px,3vw,34px) Manrope, sans-serif}.ai-usage-heading p,.ai-usage-card p{margin:0;color:#6d8195}.ai-usage-kicker{font-size:11px;font-weight:800;letter-spacing:.12em;color:#1688aa}.ai-usage-actions{display:flex;gap:8px}.ai-usage-button{min-height:40px;border:1px solid #cbd9e6;border-radius:8px;padding:8px 13px;font-weight:700;color:#173c5f;background:white;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.ai-usage-button.primary{color:white;background:#17476c;border-color:#17476c}.ai-usage-button:disabled{opacity:.55;cursor:wait}.ai-usage-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.ai-usage-kpis article,.ai-usage-card{background:white;border:1px solid #d9e4ed;border-radius:13px;padding:18px;box-shadow:0 4px 16px #12354c08}.ai-usage-kpis small,.ai-usage-kpis span{display:block;color:#71859a}.ai-usage-kpis strong{display:block;margin:8px 0;font:700 27px Manrope,sans-serif;color:#123d60}.ai-usage-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,1fr);gap:14px}.ai-usage-card h2{margin:0 0 4px;font:700 17px Manrope,sans-serif}.ai-usage-card-head{margin-bottom:16px}.ai-usage-pill{padding:6px 10px;border-radius:30px;background:#eff6fa;color:#42647e;font-size:12px}.ai-usage-bars{height:180px;display:flex;align-items:end;gap:5px;border-bottom:1px solid #dce6ee;padding:10px 2px 0;overflow:auto}.ai-usage-bar-col{height:100%;min-width:18px;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:end;gap:6px}.ai-usage-bar{display:block;width:min(22px,80%);min-height:3px;background:linear-gradient(180deg,#36b6d0,#17618b);border-radius:5px 5px 0 0}.ai-usage-bar-col small{font-size:10px;color:#71859a}.ai-usage-status{margin:0}.ai-usage-status div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #edf1f5}.ai-usage-status dt{color:#71859a}.ai-usage-status dd{margin:0;text-align:right;font-weight:700}.ai-usage-status .good{color:#11805d}.ai-usage-status .pending{color:#a66312}.ai-usage-note,.ai-usage-empty{color:#71859a}.ai-usage-filters,.ai-usage-form{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:14px 0}.ai-usage-filters label,.ai-usage-form label{display:grid;gap:5px;min-width:135px;flex:1;color:#536e84;font-size:12px;font-weight:700}.ai-usage-filters input,.ai-usage-filters select,.ai-usage-form input,.ai-usage-form textarea{width:100%;min-height:39px;box-sizing:border-box;padding:8px 10px;border:1px solid #cbd9e6;border-radius:7px;background:white;color:#183d5c;font:inherit;font-weight:500}.ai-usage-table-wrap{overflow:auto;border:1px solid #e0e8ef;border-radius:9px}.ai-usage-table{width:100%;border-collapse:collapse;min-width:900px}.ai-usage-table th,.ai-usage-table td{padding:11px 12px;border-bottom:1px solid #edf1f4;text-align:left;vertical-align:top;font-size:13px}.ai-usage-table th{background:#f5f8fa;color:#627b90;font-size:11px;text-transform:uppercase;letter-spacing:.06em}.ai-usage-table td small{display:block;margin-top:4px;color:#7b8ea0}.ai-usage-status-badge{padding:4px 8px;border-radius:20px;background:#eaf7f0;color:#08734b;font-size:11px;font-weight:800}.ai-usage-status-badge.failed{background:#fff0ed;color:#b43b2e}.ai-usage-pagination{display:flex;justify-content:space-between;align-items:center;padding-top:14px;color:#657c91}.ai-usage-pagination div{display:flex;gap:8px}.ai-usage-management{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.ai-usage-alert{padding:12px 14px;border-radius:8px}.ai-usage-alert.error{background:#fff0ed;color:#a63227}.ai-usage-alert.success{background:#eaf7f0;color:#08734b}.ai-usage-alert.warning{margin-top:12px;background:#fff7e5;color:#8e5a00}.ai-usage-empty{text-align:center;padding:24px}.ai-usage-form{align-items:end}.ai-usage-form label{min-width:180px}.ai-usage-form button{margin-top:4px}.ai-usage-form textarea{resize:vertical}@media(max-width:900px){.ai-usage-grid,.ai-usage-management{grid-template-columns:1fr}.ai-usage-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.ai-usage-heading{display:grid}.ai-usage-kpis{grid-template-columns:1fr 1fr}.ai-usage-kpis article{padding:13px}.ai-usage-kpis strong{font-size:22px}.ai-usage-card{padding:14px}.ai-usage-card-head{display:grid}.ai-usage-filters label,.ai-usage-form label{min-width:100%;flex:1 1 100%}.ai-usage-actions{width:100%}.ai-usage-actions>*{flex:1}.ai-usage-pagination{align-items:flex-start;gap:10px;flex-direction:column}}
.ai-usage-live-fx{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:14px 0;padding:12px;border:1px solid #dce8ef;border-radius:9px;background:#f7fbfd}.ai-usage-live-fx strong{font-size:20px;color:#123d60}.ai-usage-live-fx span{color:#657c91}.ai-usage-live-fx a{color:#17618b;font-size:13px}
</style>
